import { useEffect, useState } from "react";

export default function Books() {
  const [books, setBooks] = useState([]);
  const [category, setCategory] = useState("Artificial Intelligence");

  useEffect(() => {
    fetch("http://localhost:5000/books")
      .then(res => res.json())
      .then(data => setBooks(data));
  }, []);

  return (
    <div>
      <h3>Books</h3>
      <button onClick={()=>setCategory("Artificial Intelligence")}>AI</button>
      <button onClick={()=>setCategory("Data Science")}>Data</button>
      <button onClick={()=>setCategory("Others")}>Others</button>

      <ul>
        {books.filter(b=>b.category===category)
          .map(b=>(
            <li key={b.bookId}>{b.title}</li>
          ))}
      </ul>
    </div>
  );
}
